insert into public.textos_padrao (nicho, tipo_servico, tipo_texto, conteudo) values

-- =========================== 1. PINTURA ====================================
('obra_reforma', 'pintura', 'escopo',
'Execução completa dos serviços de pintura nos ambientes descritos neste orçamento. Inclui a proteção de pisos, móveis, bancadas, esquadrias e tomadas com lona plástica e fita crepe antes do início dos trabalhos. Preparação das superfícies com raspagem e remoção de partes soltas, descascadas ou com bolhas, correção de trincas e pequenos buracos com massa corrida em áreas internas e massa acrílica em áreas externas ou úmidas, lixamento e remoção do pó. Aplicação de fundo selador ou fundo preparador de paredes conforme a condição encontrada em cada superfície. Aplicação de duas demãos de tinta na cor e no acabamento definidos com o cliente, respeitando o intervalo de secagem indicado pelo fabricante entre as demãos. Recorte de cantos, rodapés, batentes e forro feito à mão para garantir linha reta e acabamento limpo. Ao final, retirada de todas as proteções, limpeza dos respingos e entrega do ambiente varrido e pronto para uso.'),

('obra_reforma', 'pintura', 'exclusoes',
'Não estão inclusos neste orçamento: o fornecimento das tintas e massas, salvo quando houver item de material descrito na lista acima; a pintura de tetos, forros, portas, janelas, portões, grades ou armários, salvo quando descritos como itens; a remoção de papel de parede, textura, grafiato ou revestimento existente; a recuperação de paredes com infiltração ativa, mofo recorrente ou reboco solto em grande extensão, que exigem tratamento prévio e serão orçados à parte; o reboco novo, o emassamento de parede nunca pintada e a regularização de superfícies fora de esquadro; a pintura de fachadas com necessidade de andaime tubular, balancim ou trabalho em altura com acesso por corda; a movimentação de móveis pesados, eletrodomésticos e objetos frágeis, que devem ser retirados do ambiente pelo cliente antes do início; serviços elétricos, troca de tomadas e interruptores; e a retirada de entulho fora do volume gerado pela própria pintura.'),

('obra_reforma', 'pintura', 'garantia',
'Garantia de 12 meses sobre a mão de obra, contados da data de conclusão do serviço, cobrindo descascamento, bolhas, falhas de aderência, manchas de emenda entre demãos e defeitos de acabamento decorrentes da execução. A garantia não cobre danos causados por infiltração, umidade ascendente, vazamento, mau uso, limpeza com produtos abrasivos, riscos, batidas, movimentação de móveis, nem o desbotamento natural da cor pela exposição ao sol e ao tempo, que varia conforme a qualidade da tinta escolhida. Tintas e materiais fornecidos pelo cliente seguem a garantia do próprio fabricante. Constatado o defeito dentro do prazo, o reparo é feito sem custo de mão de obra, mediante agendamento.'),

('obra_reforma', 'pintura', 'condicoes',
'Entrada de 40% na assinatura do orçamento, para compra de material e reserva da data na agenda. Os 60% restantes na entrega do serviço, após vistoria conjunta do ambiente. Em serviços com prazo acima de 15 dias, o saldo pode ser dividido em parcelas semanais conforme o avanço da obra, combinadas por escrito antes do início. Aceitamos Pix, dinheiro, transferência bancária e cartão de crédito em até 6 vezes, sendo que no cartão incide a taxa da operadora sobre o valor parcelado. O início dos trabalhos fica condicionado à confirmação do pagamento da entrada. Este orçamento tem validade conforme a data indicada e os preços podem ser revistos após esse prazo em razão da variação do custo dos materiais.'),

-- =========================== 2. ELÉTRICA ===================================
('obra_reforma', 'eletrica', 'escopo',
'Execução dos serviços elétricos descritos neste orçamento, seguindo a norma NBR 5410. Inclui o desligamento seguro do circuito antes de qualquer intervenção, a abertura de rasgos em alvenaria para passagem de eletrodutos quando necessário, o assentamento de caixas de passagem e caixas 4x2 e 4x4 no nível e no prumo, a passagem de cabeamento com bitola dimensionada para a carga de cada circuito e o fechamento dos rasgos com argamassa. Instalação de tomadas, interruptores, pontos de luz, luminárias e demais dispositivos previstos nos itens acima. Montagem e organização do quadro de distribuição com identificação de cada disjuntor por circuito, separação entre circuitos de iluminação, tomadas de uso geral e tomadas de uso específico, e instalação de dispositivo DR quando previsto. Ao final, teste ponto a ponto de todos os dispositivos instalados, verificação de aterramento, medição de tensão e entrega do quadro identificado, com demonstração do funcionamento ao cliente.'),

('obra_reforma', 'eletrica', 'exclusoes',
'Não estão inclusos neste orçamento: o fornecimento de fios, cabos, disjuntores, quadros, tomadas, interruptores e luminárias, salvo quando descritos como itens de material acima; o projeto elétrico assinado por engenheiro e a ART ou RRT correspondente; a troca do padrão de entrada de energia, o aumento de carga junto à concessionária e qualquer serviço no ramal de entrada, que são de responsabilidade da concessionária e exigem processo próprio; a substituição de toda a fiação do imóvel quando o orçamento previr apenas pontos específicos; o acabamento de pintura, massa ou revestimento sobre os rasgos fechados, entregues apenas com a argamassa nivelada; instalação de sistemas de automação, cerca elétrica, interfone, antena, rede de dados e câmeras, salvo se descritos; o conserto de aparelhos e eletrodomésticos; e a correção de instalações antigas fora do escopo contratado, que serão avaliadas e orçadas separadamente caso sejam encontradas durante a execução.'),

('obra_reforma', 'eletrica', 'garantia',
'Garantia de 12 meses sobre a mão de obra, contados da conclusão do serviço, cobrindo falhas de execução como mau contato, emenda mal feita, aquecimento de conexão, inversão de fase e neutro, dimensionamento incorreto de condutor e defeito na montagem do quadro. Materiais e dispositivos fornecidos por nós seguem a garantia do fabricante, normalmente de 12 meses, intermediada por nós junto ao fornecedor. A garantia não cobre queima de equipamentos por oscilação, surto ou descarga atmosférica da rede da concessionária, sobrecarga causada pela ligação de aparelhos acima da capacidade do circuito, intervenção de terceiros na instalação após a entrega, nem defeitos em materiais fornecidos pelo cliente. Qualquer alteração feita por outro profissional nos pontos executados encerra a garantia sobre o trecho alterado.'),

('obra_reforma', 'eletrica', 'condicoes',
'Entrada de 50% na aprovação do orçamento, destinada à compra de material elétrico e à reserva da data. Saldo de 50% na conclusão, após os testes finais e a entrega do quadro identificado. Em obras com prazo superior a 20 dias, o pagamento pode ser dividido por etapas concluídas, com medição combinada por escrito antes do início. Aceitamos Pix, dinheiro, transferência bancária e cartão de crédito em até 6 vezes, com a taxa da operadora acrescida no parcelamento. Serviços de emergência fora do horário comercial, aos domingos e feriados têm acréscimo, informado e aprovado antes do atendimento. Materiais comprados pelo cliente devem estar no local no dia agendado para o início, sob pena de remarcação.'),

-- ========================== 3. HIDRÁULICA ==================================
('obra_reforma', 'hidraulica', 'escopo',
'Execução dos serviços hidráulicos descritos neste orçamento, em água fria, água quente e esgoto conforme o caso. Inclui o fechamento do registro geral e o esvaziamento da tubulação antes da intervenção, a abertura de rasgos em alvenaria ou piso para acesso e passagem de tubulação quando necessário, o corte, a soldagem e o assentamento de tubos e conexões em PVC, CPVC ou PPR conforme a aplicação, com caimento correto nas linhas de esgoto para evitar retorno e entupimento. Instalação de registros, misturadores, torneiras, sifões, válvulas, caixas sifonadas e louças previstas nos itens acima. Teste de estanqueidade das linhas de água sob pressão antes do fechamento dos rasgos, para garantir que não há vazamento em nenhuma conexão nova. Fechamento dos rasgos com argamassa e limpeza do local. Ao final, religamento do sistema, verificação de vazão e pressão em cada ponto e demonstração do funcionamento ao cliente.'),

('obra_reforma', 'hidraulica', 'exclusoes',
'Não estão inclusos neste orçamento: o fornecimento de tubos, conexões, registros, metais, louças, caixas acopladas e assentos, salvo quando descritos como itens de material acima; o acabamento de pintura, revestimento, azulejo ou porcelanato sobre os rasgos fechados, entregues apenas com argamassa nivelada; a troca completa da tubulação do imóvel quando o orçamento previr apenas trechos ou pontos específicos; a limpeza e o desentupimento de rede de esgoto, caixa de gordura e fossa com equipamento de hidrojateamento; a impermeabilização de box, sacada e laje; a instalação de aquecedor a gás, boiler e toda a rede de gás, que exige profissional habilitado específico; a localização de vazamento com equipamento de geofone ou câmera, orçada à parte; a recuperação de estrutura danificada por vazamento antigo; e o reparo de problemas na rede pública ou no ramal da concessionária.'),

('obra_reforma', 'hidraulica', 'garantia',
'Garantia de 12 meses sobre a mão de obra, contados da conclusão do serviço, cobrindo vazamento em conexão executada, falha de solda, caimento incorreto de esgoto e defeito na instalação de metais e louças. Materiais fornecidos por nós seguem a garantia do fabricante. A garantia não cobre entupimento por mau uso, como descarte de gordura, fio dental, cabelo, papel e objetos na rede, nem vazamento em trecho antigo da tubulação que não fez parte do serviço contratado, nem danos causados por golpe de aríete decorrente de pressão irregular da rede, obras de terceiros ou movimentação estrutural do imóvel. Louças e metais fornecidos pelo cliente têm garantia apenas quanto à instalação, não quanto ao produto.'),

('obra_reforma', 'hidraulica', 'condicoes',
'Entrada de 50% na aprovação do orçamento, para compra de material e reserva da data. Saldo de 50% na conclusão, após o teste de estanqueidade e a vistoria conjunta. Em serviços de reforma completa de banheiro ou troca de prumada, o pagamento pode ser dividido em etapas conforme o avanço, definidas por escrito antes do início. Aceitamos Pix, dinheiro, transferência bancária e cartão de crédito em até 6 vezes, com a taxa da operadora acrescida no parcelamento. Atendimentos de emergência com vazamento ativo, fora do horário comercial, aos domingos e feriados, têm valor diferenciado, informado e aprovado antes do deslocamento. Caso a abertura da parede ou do piso revele problema diferente do diagnosticado, o serviço é interrompido e um orçamento complementar é apresentado antes de qualquer continuidade.'),

-- ======================= 4. DRYWALL / GESSO ================================
('obra_reforma', 'drywall_gesso', 'escopo',
'Execução dos serviços em drywall e gesso descritos neste orçamento. Inclui a marcação do projeto no piso e no teto conforme o layout aprovado, a fixação de guias e montantes em perfis de aço galvanizado no espaçamento correto para a altura e a carga previstas, o reforço interno nos pontos de fixação de televisão, armário, prateleira, bancada e demais cargas informadas pelo cliente, e a passagem de eletrodutos e caixas dentro da estrutura antes do fechamento. Fechamento com placas de drywall do tipo adequado a cada ambiente, sendo placa branca standard em áreas secas e placa verde resistente à umidade em áreas molhadas. Tratamento das juntas com fita e massa própria em três demãos, com lixamento entre elas, e acabamento nos cantos com cantoneira. Nos forros, nivelamento a laser ou mangueira de nível, estrutura em perfil suspensa por tirantes e previsão dos pontos de luz e de acesso. Entrega da superfície lisa, no prumo e pronta para receber pintura, com o ambiente varrido.'),

('obra_reforma', 'drywall_gesso', 'exclusoes',
'Não estão inclusos neste orçamento: a pintura, o selador e o emassamento final de nivelamento fino da superfície, salvo quando descritos como itens acima; o fornecimento de placas, perfis, massa, fita e parafusos, salvo quando descritos como material; a instalação elétrica, hidráulica e de ar-condicionado dentro da estrutura, apenas a previsão de passagem quando informada com antecedência; a demolição de paredes de alvenaria existentes e a remoção do entulho gerado por ela; a instalação de sancas, molduras e elementos decorativos não descritos; a fixação de objetos pelo cliente após a entrega em pontos sem reforço previsto, que não é coberta; o isolamento acústico com lã de vidro, lã de rocha ou placa acústica, salvo quando orçado como item; e a correção de desnível de piso ou de laje fora de esquadro que exija estrutura adicional, situação que será apontada e orçada antes da execução.'),

('obra_reforma', 'drywall_gesso', 'garantia',
'Garantia de 12 meses sobre a mão de obra, contados da conclusão, cobrindo trinca em junta tratada, desnivelamento de forro, soltura de placa, falha na fixação da estrutura e defeito de acabamento nos cantos. A garantia não cobre trincas decorrentes de acomodação natural da estrutura do imóvel, movimentação por obra vizinha, infiltração vinda de laje, telhado ou tubulação, contato com água em placa standard instalada em área seca, nem furos, batidas e danos por impacto. Também não cobre a queda de objetos fixados pelo cliente em pontos onde não havia reforço previsto e informado no momento da execução. Danos causados por umidade exigem a correção prévia da origem antes de qualquer reparo em garantia.'),

('obra_reforma', 'drywall_gesso', 'condicoes',
